import { countsLive, useClaims } from '../claims/useClaims';
import { gradeOn, usePeople } from '../people/usePeople';
import { claimDue, toCents } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, useTerms } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodOf, usePeriods, type Period } from './usePeriods';

/** A period's due-total: the dues, late charges included, of the claims that count whose date falls
 *  in it, leaving out a held person's OPEN claims (a claim whose due is n/a adds nothing); a closed
 *  period gives the due-total fixed when it was closed. */
export function usePeriodDueTotal(sheet: string): (period: Period) => bigint {
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), terms: useTerms(sheet), today: useSheetToday(sheet) };
  const personOf = new Map(people.map((p) => [p.id, p]));
  const heldOf = new Map(people.map((p) => [p.id, p.held]));
  return (period: Period) =>
    period.closed ? toCents(period.closedTotal) : claims
      .filter((c) => personOf.has(c.personId) && countsLive(c, heldOf.get(c.personId)!) && periodOf(periods, c.date)?.name === period.name)
      .reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(personOf.get(c.personId)!, c.date), c.date), floor, late) ?? 0n), 0n);
}
import { asString, useSearchParam } from '../../url/useSearchParam';
import { ClaimForm } from '../claims/ClaimForm';
import { ClaimList } from '../claims/ClaimList';
import { countsLive, sumAmounts, useClaims } from '../claims/useClaims';
import { isOverdue } from '../claims/overdue';
import { claimDue, dueTotal, formatCents, showDue } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, useTerms } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { StatementButton } from '../statements/StatementButton';
import { SummaryPanel } from '../summary/SummaryPanel';
import { HoldControl } from './HoldControl';
import { PatronControl } from './PatronControl';
import { QuickAdd } from './QuickAdd';
import { RetireControl } from './RetireControl';
import { ShowRetired, useShowRetired } from './ShowRetired';
import { gradeOn, usePeople, type Person } from './usePeople';

// Every person on the sheet in the order they were added, with their name, grade (the one in force on the sheet's today), claimed (the
// sum of their OPEN and SETTLED claims), due-total (the
// sum of their counting claims' already-rounded dues; n/a when their grade has no rate today and no settled or stated claim keeps a figure),
// whether they are retired and from when, whether they are on hold (a held person's OPEN claims count
// in neither their figures nor the sheet's totals; their SETTLED claims still do), their overdue count and
// patrons (names, sorted) and backing (their patrons' due-totals added up, skipping n/a; 0.00 with no patrons),
// their overdue count and overdue-total (how many of their counting claims are overdue, and the sum of those claims' dues with their late charges, n/a adding nothing), their statements (the statement button, how many were taken, the last one's due-total and date) and their claims; then the
// sheet's claimed-total, due-total (the people's due-totals added up, skipping n/a), overdue count and overdue-total. Retired
// people have no row unless "show retired" is on, but their claims keep counting in every total.
// Then the summary panel, worked from these same figures.
export function PeopleList() {
  const [sheet] = useSearchParam('sheet', asString);
  const [, setEditing] = useSearchParam('editPerson', asString);
  const people = usePeople(sheet);
  const [showRetired] = useShowRetired();
  const listed = showRetired ? people : people.filter((p) => !p.retired);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const terms = useTerms(sheet);
  const late = { pct: useLatePct(sheet), terms, today };
  const heldOf = new Map(people.map((p) => [p.id, p.held]));
  const live = claims.filter((c) => heldOf.has(c.personId) && countsLive(c, heldOf.get(c.personId)!));
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  const totalOf = (person: Person) =>
    dueTotal(
      live.filter((c) => c.personId === person.id),
      (date) => rateOn(rates, gradeOn(person, date), date),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
    );
  const byId = new Map(people.map((p) => [p.id, p]));
  const backing = (p: (typeof people)[number]) =>
    formatCents(p.patronIds.reduce((sum, id) => {
      const patron = byId.get(id);
      const due = patron ? totalOf(patron) : null;
      return due === null ? sum : sum + due;
    }, 0n));

  const overdue = live.filter((c) => isOverdue(c, terms, today));
  const overdueOf = (personId: string) => overdue.filter((c) => c.personId === personId);
  const overdueTotal = (cs: typeof overdue) =>
    formatCents(cs.reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId)!, c.date), c.date), floor, late) ?? 0n), 0n));
  return (
    <>
      <QuickAdd />
      <ShowRetired />
      <table data-testid="people">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Claimed</th>
            <th>Due</th>
            <th>Patrons</th>
            <th>Backing</th>
            <th>Overdue</th>
            <th>Overdue due</th>
            <th />
            <th>Retired</th>
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { claimDue, showDue } from '../rates/due';
import { claimsKey, type Claim } from './useClaims';
import { periodOf, usePeriods } from '../periods/usePeriods';
import { useFloor, useLatePct, useTerms } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { dueBy, isOverdue } from './overdue';

// A person's claims, newest first, each with its amount, date, note, status, number, opened-by, period (the one whose dates contain its date, blank for none), stated (yes when the
// person's last statement bound it), corrects (the number a correction corrects, blank for other claims) and due (fixed when it was settled, else bound by the last statement; otherwise its amount at the person's grade's rate in force on the claim's date raised to the sheet's floor, n/a when none applies; an overdue claim gains the sheet's late percent of that figure for every full 30 days overdue), due-by (its date plus the sheet's terms), overdue (yes when it is OPEN and its due-by is before the sheet's today), the status buttons (open, settle, void —
// one the claim's status does not allow is refused with the claim's error) and an edit button that
// opens a DRAFT claim in the person's claim form (cancel closes it again); editing any other claim is
// refused with the claim's error — to change an open claim, void it and add a new one.
export function ClaimList({ claims, rateOn }: { claims: Claim[]; rateOn: (date: string) => string | undefined }) {
  return (
    <ul data-testid="claims">
      {claims.map((c) => (
        <ClaimRow key={c.id} claim={c} rate={rateOn(c.date)} />
      ))}
    </ul>
  );
}

function ClaimRow({ claim: c, rate }: { claim: Claim; rate: string | undefined }) {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const [editing, setEditing] = useSearchParam('editClaim', asString);
  const queryClient = useQueryClient();
  const period = periodOf(usePeriods(sheet), c.date);
  const floor = useFloor(sheet);
  const terms = useTerms(sheet);
  const today = useSheetToday(sheet);
  const latePct = useLatePct(sheet);

  const status = useMutation({
    mutationFn: (action: 'open' | 'settle' | 'void') =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${encodeURIComponent(c.id)}/status`,
        { action, user },
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });

  const [editRefused, setEditRefused] = useState(false);

  // The next action on the row removes an old error.
  const act = (run: () => void) => {
    status.reset();
    setEditRefused(false);
    run();
  };

  const edit = () =>
    act(() => {
      if (c.status === 'DRAFT') setEditing(c.id);
      else setEditRefused(true);
    });

  return (
    <li data-testid={`claim-row-${c.id}`}>
      <span data-testid="claim-amount">{c.amount}</span>{' '}
      <span data-testid="claim-date">{c.date}</span>{' '}
      <span data-testid="claim-note">{c.note}</span>{' '}
      <span data-testid="claim-status">{c.status}</span>{' '}
      <span data-testid="claim-number">{c.number}</span>{' '}
      <span data-testid="claim-due">{showDue(claimDue(c, rate, floor, { pct: latePct, terms, today }))}</span>{' '}
      <span data-testid="claim-due-by">{dueBy(c, terms)}</span>{' '}
      <span data-testid="claim-overdue">{isOverdue(c, terms, today) ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-opened-by">{c.openedBy}</span>{' '}
      <span data-testid="claim-period">{period?.name ?? ''}</span>{' '}
      <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-corrects">{c.corrects}</span>{' '}
      <button type="button" data-testid="claim-open" onClick={() => act(() => status.mutate('open'))}>
        Open
      </button>{' '}
      <button type="button" data-testid="claim-settle" onClick={() => act(() => status.mutate('settle'))}>
        Settle
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a; `stated` is whether the last statement bound it. A claim with a negative
 *  amount is a correction: its due has no floor and no late charge. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
  corrects: string;
};

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** Whether a claim counts in the live totals: it counts, and is not OPEN while its person is held. */
export const countsLive = (c: Claim, held: boolean) => counts(c) && !(held && c.status === 'OPEN');

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const { data } = useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The amounts of the claims that count added up, shown with two decimals. Summed in whole cents
 *  so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

